-- rate(is_click|user_id+author_id|std|w=7d|a=10)
WITH p AS (SELECT *, (COALESCE(SUM(CASE WHEN is_rand = 0 THEN is_click ELSE 0 END) OVER (ORDER BY t RANGE BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING), 0) + 0.5) / (COALESCE(SUM(CASE WHEN is_rand = 0 THEN 1 ELSE 0 END) OVER (ORDER BY t RANGE BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING), 0) + 1) AS prior FROM ev) SELECT eid, (COALESCE(SUM(CASE WHEN is_rand = 0 THEN is_click ELSE 0 END) OVER (PARTITION BY user_id, author_id ORDER BY t RANGE BETWEEN 604800000 PRECEDING AND 1 PRECEDING), 0) + 10.0 * prior) / (COALESCE(SUM(CASE WHEN is_rand = 0 THEN 1 ELSE 0 END) OVER (PARTITION BY user_id, author_id ORDER BY t RANGE BETWEEN 604800000 PRECEDING AND 1 PRECEDING), 0) + 10.0) AS v FROM p;

-- recency(imp|user_id+tab|all)
SELECT eid, (t - MAX(CASE WHEN imp > 0 THEN t END) OVER (PARTITION BY user_id, tab ORDER BY t RANGE BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING)) / 1000.0 AS v FROM ev;

-- dsum(is_click|video_id|all|hl=1.469d)
WITH p AS (SELECT *, (COALESCE(SUM(is_click) OVER (ORDER BY t RANGE BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING), 0) + 0.5) / (COALESCE(SUM(1) OVER (ORDER BY t RANGE BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING), 0) + 1) AS prior FROM ev) SELECT q.eid AS eid, COALESCE(SUM((e.is_click) * exp(-(q.t - e.t) / 1000.0 / 183109.16290169267)), 0) AS v FROM p q LEFT JOIN ev e ON q.video_id = e.video_id AND e.t < q.t AND e.t >= q.t - 5076864000 GROUP BY q.eid, q.prior;

